using System;
using TinyTracks.Audio;
using TinyTracks.Building;
using TinyTracks.Cameras;
using TinyTracks.Decorations;
using TinyTracks.Inputs;
using TinyTracks.Interaction;
using TinyTracks.Performance;
using TinyTracks.SaveSystem;
using TinyTracks.Tracks;
using TinyTracks.Trains;
using TinyTracks.World;
using UnityEngine;

namespace TinyTracks.Core
{
    public enum GameMode { Menu, Build, Train, Decorate, Explore }

    /// <summary>
    /// Wires the systems together, owns the current mode and the shared undo history, and routes world taps.
    /// Scene layout (generated by the editor setup): one GameObject per system under "Systems".
    /// </summary>
    public class GameManager : MonoBehaviour
    {
        public static GameManager Instance { get; private set; }

        public ContentLibrary content;
        public InputManager input;
        public CameraController cameraController;
        public TrackNetworkManager network;
        public TrackPlacementController placement;
        public DecorationManager decorations;
        public DecorationPlacementController decoPlacement;
        public TrainManager trains;
        public WorldManager world;
        public AudioManager audioManager;
        public SaveManager save;
        public PerformanceManager performance;
        public TinyTracks.Stations.StationManager stations;

        public GameMode Mode { get; private set; } = GameMode.Menu;
        public CommandStack Commands { get; } = new CommandStack();
        public event Action<GameMode> ModeChanged;
        /// <summary>The train whistled (button or a tap on the train).</summary>
        public event Action Whistled;
        /// <summary>The child moved to another world (Sunny Valley, Snowy Valley...).</summary>
        public event Action<WorldDefinition> WorldSwitched;

        /// <summary>Seconds since the child last touched anything (drives the gentle hint hand).</summary>
        public float IdleTime => Time.unscaledTime - lastInput;
        private float lastInput;

        private void Awake()
        {
            Instance = this;
            Application.targetFrameRate = 30;
            Screen.sleepTimeout = SleepTimeout.SystemSetting;
            placement.Commands = Commands;
            decoPlacement.Commands = Commands;
            Vector2 half = world != null ? world.BuildableHalfSize : new Vector2(30f, 22f);
            placement.buildableHalfSize = half;
            decoPlacement.buildableHalfSize = half;
            if (world != null && world.world != null) cameraController.bounds = world.world.cameraHalfSize;
        }

        private void Start()
        {
            input.Tap += OnTap;
            input.Tap += _ => Touched();
            input.PanDelta += _ => Touched();
            input.Pinch += (_, __) => Touched();
            input.LongPress += _ => Touched();

            SettingsSave s = save.Settings;
            audioManager.SetVolumes(s.music, s.sfx, s.ambient);
            audioManager.SetVoiceVolume(s.voice);
            Localization.Set(s.language);
            performance.Apply(s.quality >= 0 ? (QualityPreset)s.quality : PerformanceManager.AutoDetect());
            audioManager.StartBackground();
            // Return to the world the child played last.
            WorldDefinition last = world != null ? world.Find(s.lastWorld) : null;
            if (last != null && world.world != last) world.SetWorld(last);
            SaveManager.WorldId = world != null && world.world != null ? world.world.id : "sunny_valley";
            if (world != null && world.world != null) audioManager.SetAmbience(world.world.ambience);
            LoadOrCreateWorld();
            SetMode(GameMode.Menu);
        }

        public void Touched() => lastInput = Time.unscaledTime;

        private void LoadOrCreateWorld()
        {
            WorldSave w = SaveManager.ReadWorld(out string problem);
            if (w != null)
            {
                save.Apply(w);
                Debug.Log($"[TT] Loaded world: {w.tracks.Count} pieces, {w.decorations.Count} decorations");
            }
            else
            {
                if (problem != null) Debug.LogWarning("[TT] Save unusable (" + problem + "); starting a fresh world.");
                CreateStarterWorld();
            }
            Commands.Clear();
        }

        private void CreateStarterWorld()
        {
            network.SuppressEffects = true;
            WorldManager.BuildStarterLayout(network);
            network.SuppressEffects = false;
            decorations.SuppressEffects = true;
            WorldDefinition wd = world != null ? world.world : null;
            if (wd != null && wd.starterDecorations.Count > 0)
                foreach (WorldProp p in wd.starterDecorations) decorations.Place(p.decorationId, new Vector3(p.position.x, 0f, p.position.z), p.yaw);
            else
            {
                (string id, float x, float z, float yaw)[] starter =
                {
                    ("House_A", 12f, 9f, 200f), ("Tree_Round", 17f, 5f, 0f), ("Tree_Apple", -15f, 7f, 0f), ("Tree_Pine", -19f, 1f, 30f),
                    ("Cow", -15f, -6f, 120f), ("Sheep", -13f, -10f, 200f), ("Flowers_Red", 5f, 4f, 0f), ("Flowers_Yellow", -6f, 5f, 0f),
                    ("Bush", 14f, -12f, 0f), ("Person_Conductor", -1.5f, -10.4f, 180f), ("Dog", 9f, 5f, 210f), ("Fence", -16f, -13f, 0f),
                };
                foreach (var d in starter) decorations.Place(d.id, new Vector3(d.x, 0f, d.z), d.yaw);
            }
            decorations.SuppressEffects = false;
            trains.AutoPlace(new Vector3(-2f, 0f, -8f));
            save.SaveWorld();
        }

        // ------------------------------------------------------------------------------------------------ actions
        public void Play()
        {
            Touched();
            if (network.Graph.Count == 0) { SetMode(GameMode.Build); return; }
            if (trains.Current == null) trains.AutoPlace(cameraController.Target);
            SetMode(GameMode.Train);
        }

        public void NewWorld()
        {
            trains.RemoveAll();
            stations?.ClearAll();
            Commands.Execute(new ClearWorldCommand(network, decorations));
            Commands.Clear();
            save.DeleteWorld();
            CreateStarterWorld();
            cameraController.ResetView();
            AudioManager.Sfx(AudioManager.Clips?.tada, 0.7f);
            SetMode(GameMode.Build);
        }

        /// <summary>Saves this world, then switches the scenery and loads (or starts) the other world's railway.</summary>
        public void SwitchWorld(string id)
        {
            WorldDefinition next = world != null ? world.Find(id) : null;
            if (next == null || next == world.world) return;
            save.Flush();
            trains.RemoveAll();
            stations?.ClearAll();
            placement.Deselect();
            decoPlacement.Deselect();
            SaveManager.WorldId = next.id;
            save.Settings.lastWorld = next.id;
            save.SaveSettings();
            // Clear this world's railway and scenery items before the next world loads or builds its starter loop.
            network.SuppressEffects = true;
            decorations.SuppressEffects = true;
            network.ClearAll();
            decorations.ClearAll();
            network.SuppressEffects = false;
            decorations.SuppressEffects = false;
            Commands.Clear();
            world.SetWorld(next);
            Vector2 half = next.buildableHalfSize;
            placement.buildableHalfSize = half;
            decoPlacement.buildableHalfSize = half;
            cameraController.bounds = next.cameraHalfSize;
            LoadOrCreateWorld();
            cameraController.ResetView();
            AudioManager.Sfx(AudioManager.Clips?.tada, 0.6f);
            WorldSwitched?.Invoke(next);
        }

        public void ClearRailway()
        {
            trains.RemoveAll();
            stations?.ClearAll();
            Commands.Execute(new ClearWorldCommand(network, decorations));
            AudioManager.Sfx(AudioManager.Clips?.trackRemove);
        }

        public void GoHome()
        {
            save.Flush();
            SetMode(GameMode.Menu);
        }

        public void SetMode(GameMode m)
        {
            Mode = m;
            placement.SetActive(m == GameMode.Build);
            decoPlacement.SetActive(m == GameMode.Decorate);
            if (m == GameMode.Menu) cameraController.ResetView();
            if (m == GameMode.Train && trains.Current != null) cameraController.Follow(trains.Current.Anchor);
            else if (m != GameMode.Train) cameraController.StopFollowing();
            ModeChanged?.Invoke(m);
        }

        public bool Undo()
        {
            if (!Commands.Undo()) { AudioManager.Sfx(AudioManager.Clips?.invalid); return false; }
            AudioManager.Sfx(AudioManager.Clips?.undo);
            return true;
        }

        public bool Redo()
        {
            if (!Commands.Redo()) { AudioManager.Sfx(AudioManager.Clips?.invalid); return false; }
            AudioManager.Sfx(AudioManager.Clips?.undo);
            return true;
        }

        // ------------------------------------------------------------------------------------------------ train controls
        public void TrainGo()
        {
            if (trains.Current == null && !trains.AutoPlace(cameraController.Target))
            {
                AudioManager.Sfx(AudioManager.Clips?.invalid);
                return;
            }
            trains.Current.Go();
            if (Mode == GameMode.Train && !cameraController.IsFollowing) cameraController.Follow(trains.Current.Anchor);
        }

        public void TrainStop() => trains.Current?.Stop();

        /// <summary>The child painted the current train (null = back to its own colours).</summary>
        public event Action<Color?> TrainPainted;

        public void PaintTrain(Color? colour)
        {
            if (trains.Current == null) { AudioManager.Sfx(AudioManager.Clips?.invalid); return; }
            trains.Current.Paint(colour);
            if (trains.Current.Locomotive != null) Juice.Squash(trains.Current.Locomotive.transform, 0.12f, 0.35f);
            AudioManager.Sfx(AudioManager.Clips?.placeDecor, 0.8f);
            save.MarkDirty();
            TrainPainted?.Invoke(colour);
        }

        /// <summary>Adds another train (up to three) on free track and drives it.</summary>
        public bool AddTrain()
        {
            TrainController t = trains.AddTrain();
            if (t == null) { AudioManager.Sfx(AudioManager.Clips?.invalid); return false; }
            if (Mode == GameMode.Train) cameraController.Follow(t.Anchor);
            return true;
        }
        public void Whistle()
        {
            if (trains.Current != null) trains.Current.Whistle(); else AudioManager.Sfx(AudioManager.Clips?.whistle);
            Whistled?.Invoke();
        }
        public void Bell() { if (trains.Current != null) trains.Current.Bell(); else AudioManager.Sfx(AudioManager.Clips?.bell); }

        public void ChangeSpeed(int delta)
        {
            if (trains.Current == null) return;
            int before = trains.Current.SpeedLevel;
            trains.Current.SetSpeedLevel(before + delta);
            AudioManager.Sfx(trains.Current.SpeedLevel != before ? AudioManager.Clips?.buttonToggle : AudioManager.Clips?.invalid);
        }

        public void ToggleFollow()
        {
            if (cameraController.IsFollowing || trains.Current == null) cameraController.StopFollowing();
            else cameraController.Follow(trains.Current.Anchor);
        }

        // ------------------------------------------------------------------------------------------------ taps
        private void OnTap(Vector2 screen)
        {
            if (Mode == GameMode.Menu) return;
            Camera cam = cameraController.Cam;
            Ray ray = cam.ScreenPointToRay(screen);

            // The train always answers a tap with a whistle.
            // A train always answers a tap with a whistle, and becomes the one the controls drive.
            TrainController tapped = trains.TrainHit(ray);
            if (tapped != null)
            {
                if (tapped != trains.Current)
                {
                    trains.Select(tapped);
                    if (Mode == GameMode.Train) cameraController.Follow(tapped.Anchor);
                }
                tapped.Whistle();
                Whistled?.Invoke();
                return;
            }

            if (Mode == GameMode.Build && placement.HandleTap(screen)) return;
            if (Mode == GameMode.Decorate && decoPlacement.HandleTap(screen)) return;

            if (Mode == GameMode.Train && InputManager.ScreenToGround(cam, screen, 0f, out Vector3 g))
            {
                if (network.TryFlipSwitchNear(g, 1.6f)) return;
                if (trains.Current == null && trains.PlaceNear(g, 3f)) { cameraController.Follow(trains.Current.Anchor); return; }
            }
            if (Mode == GameMode.Explore && InputManager.ScreenToGround(cam, screen, 0f, out Vector3 e) && network.TryFlipSwitchNear(e, 1.4f)) return;

            if (Physics.Raycast(ray, out RaycastHit hit, 400f))
            {
                Interactable it = hit.collider.GetComponentInParent<Interactable>();
                if (it != null) it.OnTap();
            }
        }
    }
}
